pub fn pitch_class(note: u8) -> PitchClass {
    match Int::rem0(note, 12u8) {
        0 => {
            return PitchClass::C;
        }
        1 => {
            return PitchClass::CSharp;
        }
        2 => {
            return PitchClass::D;
        }
        3 => {
            return PitchClass::DSharp;
        }
        4 => {
            return PitchClass::E;
        }
        5 => {
            return PitchClass::F;
        }
        6 => {
            return PitchClass::FSharp;
        }
        7 => {
            return PitchClass::G;
        }
        8 => {
            return PitchClass::GSharp;
        }
        9 => {
            return PitchClass::A;
        }
        10 => {
            return PitchClass::ASharp;
        }
        11 => {
            return PitchClass::B;
        }
        _ => {
            return PitchClass::C;
        }
    }
}

