pub fn manufacturer_name(identifier: u32, extended: bool) -> Option<Manufacturer> {
    if extended {
        return if (identifier == 8233u32) {
            Some(Manufacturer::Novation)
        } else {
            None
        };
    }
    match identifier {
        1 => {
            return Some(Manufacturer::Sequential);
        }
        4 => {
            return Some(Manufacturer::Moog);
        }
        64 => {
            return Some(Manufacturer::Kawai);
        }
        65 => {
            return Some(Manufacturer::Roland);
        }
        66 => {
            return Some(Manufacturer::Korg);
        }
        67 => {
            return Some(Manufacturer::Yamaha);
        }
        68 => {
            return Some(Manufacturer::Casio);
        }
        71 => {
            return Some(Manufacturer::Akai);
        }
        125 => {
            return Some(Manufacturer::Educational);
        }
        126 => {
            return Some(Manufacturer::UniversalNonRealtime);
        }
        127 => {
            return Some(Manufacturer::UniversalRealtime);
        }
        8233 => {
            return Some(Manufacturer::Novation);
        }
        _ => {
            return None;
        }
    }
}

pub fn validate(config: &Config) -> Option<String> {
    return if (config.percussion_channel > 15u8) {
        Some(String::from("decode.config.midiChannel"))
    } else {
        None
    };
}

/// The `midi-semantics` decoder node.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MidiSemantics {
    config: Config,
}

impl MidiSemantics {
    /// A decoder for `config`.
    pub fn new(config: Config) -> Result<Self, ConfigError> {
        config.validate()?;
        Ok(Self { config })
    }

    /// The configuration.
    pub fn config(&self) -> &Config {
        &self.config
    }

    /// The input of the decoder added as `node`.
    pub fn input(node: NodeId) -> InputRef<MidiEvent> {
        InputRef::of_node(node, 0)
    }

    /// The event output of the decoder added as `node`.
    pub fn events(node: NodeId) -> OutputRef<Event> {
        OutputRef::of_node(node, 0)
    }
}

impl Node for MidiSemantics {
    fn spec(&self) -> NodeSpec {
        NodeSpec {
            name: "midi-semantics".into(),
            inputs: vec![InputSpec::new::<MidiEvent>("bus", self.config.requires())],
            outputs: vec![OutputSpec::new::<Event>("events", self.config.props())],
        }
    }

    fn start(self: Box<Self>, mut io: Io) -> NodeFuture {
        let rate = io.time_base().map_or(0, |base| base.rate_hz);
        let state = State::new(self.config, rate);
        Box::pin(run_stream(state, io.input(0), io.output(0)))
    }
}

/// The decoder's state: its configuration, the source's rate and its fields.
struct State {
    config: Config,
    rate: u64,
    sysex: Option<u64>,
    count: u32,
    identifier: u32,
    extended: bool,
}

impl State {
    fn new(config: Config, rate: u64) -> Self {
        let sysex: Option<u64> = None;
        let count: u32 = 0u32;
        let identifier: u32 = 0u32;
        let extended: bool = false;
        Self {
            config,
            rate,
            sysex,
            count,
            identifier,
            extended,
        }
    }

    fn hold(&self) -> Option<u64> {
        None
    }

    fn on_gap(&mut self, _range: TickRange) {
        self.sysex = None;
        self.count = 0u32;
    }

    async fn run(&mut self, io: &mut StreamIo<MidiEvent, Event>) -> Result<(), Cut> {
        loop {
            let received: Received<MidiEvent> = self.next(io).await?;
            let e: MidiEvent = received.event;
            let at: Provenance = received.at;
            match e.clone() {
                MidiEvent::ChannelMessage {
                    channel,
                    data1,
                    data2,
                    message,
                    status,
                    ..
                } => {
                    if ((status == ChannelStatus::NoteOn)
                        || ((status == ChannelStatus::NoteOff)
                            || (status == ChannelStatus::PolyPressure)))
                    {
                        let mut action: Action = Action::On;
                        if ((status == ChannelStatus::NoteOff)
                            || ((status == ChannelStatus::NoteOn)
                                && if let Some(data2_2) = data2 {
                                    (data2_2 == 0u8)
                                } else {
                                    false
                                }))
                        {
                            action = Action::Off;
                        }
                        if (status == ChannelStatus::PolyPressure) {
                            action = Action::Pressure;
                        }
                        let oct: u8 = Int::div0(data1, 12u8);
                        io.out
                            .emit(
                                at,
                                Event::Note {
                                    message,
                                    channel,
                                    note: data1,
                                    pitch_class: pitch_class(data1),
                                    octave: if (oct == 0u8) {
                                        1u8
                                    } else {
                                        Int::wsub(oct, 1u8)
                                    },
                                    below_zero: (oct == 0u8),
                                    action,
                                    value: data2,
                                    drum: if (channel == self.config.percussion_channel) {
                                        drum_name(data1)
                                    } else {
                                        None
                                    },
                                },
                            )
                            .await;
                    } else {
                        if (status == ChannelStatus::ControlChange) {
                            let lsb: bool = ((data1 >= 32u8) && (data1 <= 63u8));
                            io.out
                                .emit(
                                    at,
                                    Event::Controller {
                                        message,
                                        channel,
                                        number: data1,
                                        controller: controller_name(if lsb {
                                            Int::wsub(data1, 32u8)
                                        } else {
                                            data1
                                        }),
                                        lsb,
                                        value: data2,
                                    },
                                )
                                .await;
                        } else {
                            if (status == ChannelStatus::PitchBend) {
                                let high: Option<u8> = data2;
                                if let Some(high_2) = high {
                                    let value: u16 = Int::wadd(
                                        Int::wmul((high_2 as u16), 128u16),
                                        u16::from(data1),
                                    );
                                    let negative: bool = (value < 8192u16);
                                    io.out
                                        .emit(
                                            at,
                                            Event::PitchBend {
                                                message,
                                                channel,
                                                value,
                                                magnitude: if negative {
                                                    Int::wsub(8192u16, value)
                                                } else {
                                                    Int::wsub(value, 8192u16)
                                                },
                                                negative,
                                            },
                                        )
                                        .await;
                                }
                            }
                        }
                    }
                }
                _ => match e.clone() {
                    MidiEvent::SystemCommon {
                        data1,
                        data2,
                        message,
                        status,
                        ..
                    } => {
                        let low: Option<u8> = data1;
                        if let Some(low_2) = low {
                            if (status == CommonStatus::TimeCodeQuarterFrame) {
                                io.out
                                    .emit(
                                        at,
                                        Event::QuarterFrame {
                                            message,
                                            piece: Int::shr(low_2, 4),
                                            value: (low_2 & 15u8),
                                        },
                                    )
                                    .await;
                            }
                            if (status == CommonStatus::SongPositionPointer) {
                                let high: Option<u8> = data2;
                                if let Some(high_2) = high {
                                    let value: u16 = Int::wadd(
                                        Int::wmul((high_2 as u16), 128u16),
                                        u16::from(low_2),
                                    );
                                    io.out
                                        .emit(
                                            at,
                                            Event::SongPosition {
                                                message,
                                                midi_beats: value,
                                                midi_clocks: Int::wmul((value as u32), 6u32),
                                            },
                                        )
                                        .await;
                                }
                            }
                        }
                    }
                    _ => match e.clone() {
                        MidiEvent::Sysex {
                            bytes,
                            message,
                            offset,
                            ..
                        } => {
                            if (offset == 0u32) {
                                self.sysex = Some(message);
                                self.count = 0u32;
                                self.identifier = 0u32;
                                self.extended = false;
                            }
                            if (if let Some(sysex) = self.sysex {
                                (sysex != message)
                            } else {
                                true
                            } || (offset != self.count))
                            {
                                continue;
                            }
                            for byte in bytes {
                                if (self.count == 0u32) {
                                    self.extended = (byte == 0u8);
                                    self.identifier = u32::from(byte);
                                } else {
                                    if (self.extended && (self.count < 3u32)) {
                                        self.identifier =
                                            (Int::shl(self.identifier, 8) | u32::from(byte));
                                    }
                                }
                                self.count = Int::wadd(self.count, 1u32);
                                if (((!self.extended) && (self.count == 1u32))
                                    || (self.extended && (self.count == 3u32)))
                                {
                                    io.out
                                        .emit(
                                            at,
                                            Event::Manufacturer {
                                                message,
                                                identifier: self.identifier,
                                                extended: self.extended,
                                                manufacturer: manufacturer_name(
                                                    self.identifier,
                                                    self.extended,
                                                ),
                                            },
                                        )
                                        .await;
                                }
                            }
                        }
                        _ => match e.clone() {
                            MidiEvent::SysexEnd { .. } => {
                                self.sysex = None;
                            }
                            _ => {}
                        },
                    },
                },
            }
        }
    }
}

impl StreamDecoder for State {
    type Lower = MidiEvent;
    type Event = Event;

    fn hold(&self) -> Option<u64> {
        State::hold(self)
    }

    async fn run(&mut self, io: &mut StreamIo<MidiEvent, Event>) -> Result<(), Cut> {
        State::run(self, io).await
    }

    async fn on_gap(&mut self, io: &mut StreamIo<MidiEvent, Event>, range: TickRange) {
        State::on_gap(self, range);
    }

    async fn on_end(&mut self, _io: &mut StreamIo<MidiEvent, Event>, _tick: u64) {}

    async fn on_progress(&mut self, _io: &mut StreamIo<MidiEvent, Event>, _tick: u64) {}
}
